{
  "extracted_concepts": [
    {
      "name": "多维随机变量",
      "aliases": [
        "multivariate random variable",
        "n维随机变量"
      ],
      "definition_snippet": "设 X₁, X₂, ..., Xₙ 是定义在同一概率空间上的随机变量，则 (X₁, X₂, ..., Xₙ) 称为 n 维随机变量。",
      "category": "concept"
    },
    {
      "name": "二维随机变量",
      "aliases": [
        "two-dimensional random variable",
        "二维随机向量"
      ],
      "definition_snippet": "n=2 时的多维随机变量，常记为 (X, Y)。",
      "category": "concept"
    },
    {
      "name": "随机变量",
      "aliases": [
        "random variable",
        "随机变数"
      ],
      "definition_snippet": "定义在概率空间上的变量，是构成多维随机变量的基本对象。",
      "category": "concept"
    },
    {
      "name": "概率空间",
      "aliases": [
        "probability space",
        "概率测度空间"
      ],
      "definition_snippet": "随机变量定义所在的公共空间。",
      "category": "concept"
    },
    {
      "name": "联合分布",
      "aliases": [
        "joint distribution",
        "联合分布律"
      ],
      "definition_snippet": "多维随机变量整体的概率分布，完全决定边缘分布。",
      "category": "concept"
    },
    {
      "name": "联合分布函数",
      "aliases": [
        "joint distribution function",
        "联合累积分布函数"
      ],
      "definition_snippet": "F(x, y) = P(X ≤ x, Y ≤ y)。",
      "category": "concept"
    },
    {
      "name": "联合概率密度",
      "aliases": [
        "joint probability density",
        "联合密度函数"
      ],
      "definition_snippet": "二维连续型随机变量的密度 f(x, y)，用于边缘密度、条件密度和卷积公式。",
      "category": "concept"
    },
    {
      "name": "边缘分布",
      "aliases": [
        "marginal distribution",
        "边缘分布律"
      ],
      "definition_snippet": "由联合分布得到的单个随机变量的分布。",
      "category": "concept"
    },
    {
      "name": "边缘分布函数",
      "aliases": [
        "marginal distribution function",
        "边缘累积分布函数"
      ],
      "definition_snippet": "F_X(x)=F(x,+∞)，F_Y(y)=F(+∞,y)。",
      "category": "concept"
    },
    {
      "name": "边缘概率密度",
      "aliases": [
        "marginal probability density",
        "边缘密度"
      ],
      "definition_snippet": "f_X(x)=∫f(x,y)dy，f_Y(y)=∫f(x,y)dx。",
      "category": "concept"
    },
    {
      "name": "条件分布",
      "aliases": [
        "conditional distribution",
        "条件分布律"
      ],
      "definition_snippet": "在另一个随机变量取某值条件下随机变量的分布。",
      "category": "concept"
    },
    {
      "name": "条件概率密度",
      "aliases": [
        "conditional probability density",
        "条件密度"
      ],
      "definition_snippet": "f_{X|Y}(x|y)=f(x,y)/f_Y(y)。",
      "category": "concept"
    },
    {
      "name": "条件分布函数",
      "aliases": [
        "conditional distribution function",
        "条件累积分布函数"
      ],
      "definition_snippet": "F_{X|Y}(x|y)=P(X ≤ x | Y = y)。",
      "category": "concept"
    },
    {
      "name": "条件概率",
      "aliases": [
        "conditional probability",
        "条件概率值"
      ],
      "definition_snippet": "在给定条件下事件发生的概率，是条件分布函数的基础。",
      "category": "concept"
    },
    {
      "name": "随机变量的独立性",
      "aliases": [
        "independence of random variables",
        "独立性"
      ],
      "definition_snippet": "X与Y独立 ⟺ F(x,y)=F_X(x)F_Y(y) 或 f(x,y)=f_X(x)f_Y(y)。",
      "category": "property"
    },
    {
      "name": "卷积公式",
      "aliases": [
        "convolution formula",
        "卷积公式"
      ],
      "definition_snippet": "f_Z(z)=∫_{-∞}^{+∞} f(x,z-x)dx，用于 Z=X+Y 的密度。",
      "category": "theorem"
    },
    {
      "name": "两个随机变量函数的分布",
      "aliases": [
        "distribution of functions of two random variables",
        "二元随机变量函数的分布"
      ],
      "definition_snippet": "研究 Z=X+Y、Z=max(X,Y)、Z=min(X,Y) 等函数的分布。",
      "category": "concept"
    },
    {
      "name": "X+Y的分布",
      "aliases": [
        "distribution of sum",
        "和的分布"
      ],
      "definition_snippet": "Z=X+Y 的分布，可用卷积公式求密度。",
      "category": "concept"
    },
    {
      "name": "max(X,Y)的分布",
      "aliases": [
        "distribution of maximum",
        "最大值分布"
      ],
      "definition_snippet": "独立时 F_max(z)=F_X(z)F_Y(z)。",
      "category": "concept"
    },
    {
      "name": "min(X,Y)的分布",
      "aliases": [
        "distribution of minimum",
        "最小值分布"
      ],
      "definition_snippet": "独立时 F_min(z)=1-(1-F_X(z))(1-F_Y(z))。",
      "category": "concept"
    },
    {
      "name": "分布函数",
      "aliases": [
        "distribution function",
        "累积分布函数"
      ],
      "definition_snippet": "描述随机变量取值不超过某值的概率，如 F(x,y) 与 F_X(x)。",
      "category": "concept"
    },
    {
      "name": "概率",
      "aliases": [
        "probability",
        "概率值"
      ],
      "definition_snippet": "事件发生可能性的度量，如 P(X≤x,Y≤y)。",
      "category": "concept"
    }
  ],
